actions.script:
const text = value => String(value ?? '').trim()
const draft = Object.assign({}, hireDraft, {
    organizationPartyId: text(organizationPartyId) || null,
    partyId: text(partyId) || null,
    firstName: text(firstName),
    lastName: text(lastName),
    preferredName: text(preferredName),
    workEmail: text(workEmail),
    workPhone: text(workPhone),
    confirmNewPerson: confirmNewPerson === 'Y' ? 'Y' : ''
})
// a Hire sent twice answers the first: the draft's operation key, made once
if (!draft.operationKey) draft.operationKey = 'HIRE-' + ec.user.userId + '-' + ec.user.timestampMillis(ec.user.nowTimestamp)
if (ec.web) ec.web.sessionAttributes.peopleHireDraft = JSON.stringify(draft)
if (!draft.organizationPartyId) ec.message.addValidationError(null, 'organizationPartyId', null, 'Choose the employer', null)
if (!draft.partyId && !(draft.firstName && draft.lastName))
    ec.message.addValidationError(null, 'partyId', null, 'Choose the person, or give a new person\'s first and last names', null)
if (ec.message.hasError()) return
const previewed = ec.service.sync().name('mantle.humanres.PeopleServices.preview#Hire').parameters({
    organizationPartyId: draft.organizationPartyId, partyId: draft.partyId, firstName: draft.firstName,
    lastName: draft.lastName, workEmail: draft.workEmail, confirmNewPerson: draft.confirmNewPerson === 'Y'}).call()
if (ec.message.hasError()) return
// the person's refusals belong to this step; the terms' to the next
for (const finding of Array.from(previewed?.findings || []))
    if (finding.severity === 'error' && ['PERSON_REQUIRED', 'PERSON_MATCHES'].includes(finding.code))
        ec.message.addError(finding.message)
